1	package codex
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"log/slog"
8		"os"
9		"time"
10	
11		"github.com/entireio/cli/cmd/entire/cli/logging"
12		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
13	)
14	
15	// Polling/tailing cadence for the rollout token tailer.
16	const (
17		rolloutPollInterval = 300 * time.Millisecond
18		rolloutPollAttempts = 100 // ~30s for codex to create the rollout file
19		rolloutTailInterval = 400 * time.Millisecond
20		rolloutReadChunk    = 8192
21	)
22	
23	// tailRolloutTokens resolves the codex rollout transcript for threadID and
24	// tails it, emitting a cumulative reviewtypes.Tokens event for every
25	// token_count codex writes (~once per model turn). codex's `exec --json`
26	// stdout only carries usage on the terminal turn.completed envelope, and a
27	// review is usually a single turn — so without this the TUI shows no token
28	// movement until the run ends. The rollout file is the same source codex's
29	// interactive UI reads for its live token counter.
30	//
31	// token_count.total_token_usage is a running total, so each emission is an
32	// absolute count — matching the TUI's overwrite-not-sum semantics. Duplicate
33	// totals are suppressed so we only emit on real movement.
34	//
35	// Returns when stop is closed (the stdout stream ended) or the rollout file
36	// never appears. The caller must wait for this to return before closing the
37	// event channel (see parseCodexOutputBuf), so a send here can never race a
38	// channel close.
39	func tailRolloutTokens(threadID string, out chan<- reviewtypes.Event, stop <-chan struct{}) {
40		ctx := context.Background()
41		sessionDir, err := (&CodexAgent{}).GetSessionDir("")
42		if err != nil {
43			logging.Debug(ctx, "codex token tail: session dir unresolved", slog.String("error", err.Error()))
44			return
45		}
46		path := waitForRollout(sessionDir, threadID, stop)
47		if path == "" {
48			return
49		}
50		f, err := os.Open(path) //nolint:gosec // path is a glob match under codex's session dir, not user input
51		if err != nil {
52			logging.Debug(ctx, "codex token tail: open rollout failed", slog.String("error", err.Error()))
53			return
54		}
55		defer f.Close()
56	
57		// Tail via os.File.Read rather than bufio.Reader: bufio is sticky on EOF
58		// and would never observe lines codex appends after we first catch up.
59		var pending []byte
